struct MyClass {};

// 1. Basic Type Information
using std::is_integral_v;
using std::is_compound_v;

constexpr bool is_int_integral = is_integral_v<int>;   // true
constexpr bool is_class_compound = is_compound_v<MyClass>; // true
constexpr bool is_ptr_compound = is_compound_v<int*>;      // true

// 2. Checking for Pointer Types
using std::is_pointer_v;
using std::is_member_pointer_v;

constexpr bool is_raw_ptr = is_pointer_v<double*>;       // true
constexpr bool is_not_ptr = is_pointer_v<double&>;       // false
constexpr bool is_member_ptr = is_member_pointer_v<int MyClass::*>; // true

// 3. Extracting Pointed-to Type
using std::remove_pointer_t;

using OriginalType = volatile int* const;
using BaseType = remove_pointer_t<OriginalType>; // volatile int

static_assert(std::is_same_v<BaseType, volatile int>);
static_assert(std::is_same_v<remove_pointer_t<float>, float>);
